// Auto-submit review for V8 Energy Drink
// This script fills out and submits a 5-star review with the specified text

async function submitV8EnergyDrinkReview() {
    try {
        console.log("Starting V8 Energy Drink review submission...");

        // Wait for page elements to load
        await waitForElements();

        // Select 5-star rating
        const fiveStarRadio = document.querySelector('input[name="rating"][value="5"]');
        if (fiveStarRadio) {
            fiveStarRadio.checked = true;
            console.log("Selected 5-star rating");
        } else {
            throw new Error("Could not find 5-star rating element");
        }

        // Fill in review text
        const reviewTextArea = document.getElementById('review-text');
        const reviewText = "Great energy drink! The pomegranate blueberry flavor is refreshing and the energy boost from green tea is smooth and sustained. Highly recommend for anyone looking for a healthier energy option.";

        if (reviewTextArea) {
            reviewTextArea.value = reviewText;
            console.log("Filled review text");
        } else {
            throw new Error("Could not find review text area");
        }

        // Log review details
        console.log('Review details:');
        console.log('Rating: 5 stars');
        console.log('Review text:', reviewText);

        // Submit the form
        const reviewForm = document.getElementById('review-form');
        if (reviewForm) {
            // Create and dispatch submit event
            const submitEvent = new Event('submit', { cancelable: true });
            const result = reviewForm.dispatchEvent(submitEvent);
            console.log('Review submitted successfully');

            // Show success message
            alert('Thank you for your review!\\n\\nRating: 5 stars\\nReview: ' + reviewText);
        } else {
            throw new Error("Could not find review form");
        }

    } catch (error) {
        console.error('Error submitting review:', error);
        alert('Error submitting review: ' + error.message);
    }
}

// Helper function to wait for elements to appear
function waitForElements() {
    return new Promise((resolve, reject) => {
        let attempts = 0;
        const maxAttempts = 50; // Prevent infinite loop

        const checkElements = setInterval(() => {
            attempts++;

            const hasReviewText = document.getElementById('review-text');
            const hasRating = document.querySelector('input[name="rating"][value="5"]');

            if (hasReviewText && hasRating) {
                clearInterval(checkElements);
                resolve();
            } else if (attempts >= maxAttempts) {
                clearInterval(checkElements);
                reject(new Error("Timeout waiting for form elements"));
            }
        }, 200); // Check every 200ms
    });
}

// Execute the review submission
submitV8EnergyDrinkReview();

